typedef struct { void *ctx; int (*invoke)(void *, const msg_t *, msg_t *); } activator;

static int on_message(const activator *a, const msg_t *in) {
    msg_t out = {0};
    int rc = a->invoke(a->ctx, in, &out);   /* ordinary service, transport-agnostic */
    if (rc != 0) return send_invalid(in, rc);
    return channel_send(reply_of(in), &out);
}
